/// <summary>
///     Data Contract class for <c>AVASalesOrderDelegationReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Data Contract class for the <c>AVASalesOrderDelegationReport</c> SSRS Report.
/// </remarks>
[
    DataContractAttribute
]
    public class AVASalesOrderDelegationReportContract
{
    CreatedTransactionId        contractCreatedTransactionId;
    RefRecId                    contractSalesTableRefRecId;
    SalesId                     contractSalesId;
    SalesTableMode              contractPrintMode;

}

